import json,math
from pathlib import Path
P=Path(__file__).resolve().parent;x=json.loads((P/'atd_inputs.json').read_text());t={k:x['fy2026'][k]+x['q1fy2027'][k]-x['q1fy2026'][k] for k in x['fy2026']};fx=x['fx_usd_per_eur']/x['fx_cad_per_eur'];mc=x['price']*fx*x['shares_diluted_m'];debt=sum(x[k] for k in ['financial_debt_current','financial_debt_noncurrent','lease_liabilities_current','lease_liabilities_noncurrent']);ev=mc+debt+x['pension_liability']+x['redemption_liability']-x['cash'];norm=t['ebit']-x['normalization_legal_recovery_gain'];out={'ticker':x['ticker'],'price_date':x['price_date'],'price_usd_derived':x['price']*fx,'usd_per_cad':fx,'market_cap_proxy_usdm':mc,'debt_with_leases_usdm':debt,'ev_usdm':ev,'ev_plus_all_book_nci_sensitivity':ev+x['noncontrolling_interest_book'],'ttm':t,'normalized_ebit':norm,'ev_ebit':ev/t['ebit'],'ev_normalized_ebit':ev/norm,'ev_normalized_ebit_nci_sensitivity':(ev+x['noncontrolling_interest_book'])/norm,'ev_revenue':ev/t['revenue'],'ev_ebitda_mechanical':ev/(t['ebit']+t['da_and_impairment']),'pe_quarterly_sum_reported':x['price']*fx/t['eps_diluted'],'posture':'Screen only, IFRS16 capitalized leases; not a target multiple.'};(P/'atd_results.json').write_text(json.dumps(out,indent=2)+'\n');assert math.isclose(t['ebit'],4727.8);assert math.isclose(norm,4466.9);assert ev>mc;print(json.dumps(out,indent=2))
